use crate::{documents::config::ContentConfig, lifecycle::policy::TemporalConfig};
use anyhow::{Result, ensure};
use serde::Deserialize;

#[derive(Clone, Debug, Deserialize, utoipa::ToSchema)]
#[serde(deny_unknown_fields)]
pub struct ProcessingConfig {
    #[serde(default)]
    pub enabled: bool,
    pub temporal: TemporalConfig,
    /// Generated by KF features.scheduler.export_contract from the deployed KF configuration.
    pub worker_contract_file: String,
    pub worker: WorkerIdentity,
    pub derived: ContentConfig,
    #[serde(default)]
    pub limits: Limits,
}
#[derive(Clone, Debug, Deserialize, utoipa::ToSchema)]
#[serde(deny_unknown_fields)]
pub struct WorkerIdentity {
    pub issuer: String,
    pub audience: String,
    pub client_id: String,
}
#[derive(Clone, Debug, Deserialize, utoipa::ToSchema)]
#[serde(default, deny_unknown_fields)]
pub struct Limits {
    pub pending: u32,
    pub batch: u32,
    pub poll_seconds: u64,
    pub queue_seconds: u32,
    pub execution_seconds: u32,
    pub output_bytes: i64,
    pub derived_bytes: i64,
    pub artifacts: u32,
    pub chunks: u32,
    pub generations: u32,
}
impl Default for Limits {
    fn default() -> Self {
        Self {
            pending: 1000,
            batch: 20,
            poll_seconds: 5,
            queue_seconds: 3600,
            execution_seconds: 86400,
            output_bytes: 512 * 1024 * 1024,
            derived_bytes: 20 * 1024 * 1024 * 1024,
            artifacts: 2000,
            chunks: 100000,
            generations: 32,
        }
    }
}
impl ProcessingConfig {
    pub fn validate(&self, originals: &ContentConfig) -> Result<()> {
        self.derived.validate()?;
        ensure!(
            self.derived.bucket != originals.bucket || self.derived.endpoint != originals.endpoint,
            "processing derived storage must use a separate bucket"
        );
        ensure!(
            self.worker.issuer.starts_with("https://")
                || (self.derived.allow_insecure && self.worker.issuer.starts_with("http://")),
            "processing worker issuer requires HTTPS"
        );
        ensure!(
            !self.worker.audience.trim().is_empty() && !self.worker.client_id.trim().is_empty(),
            "processing worker identity is required"
        );
        let l = &self.limits;
        ensure!(
            (1..=10000).contains(&l.pending)
                && (1..=100).contains(&l.batch)
                && (1..=60).contains(&l.poll_seconds),
            "invalid processing admission limits"
        );
        ensure!(
            (60..=86400).contains(&l.queue_seconds)
                && (300..=604800).contains(&l.execution_seconds),
            "invalid processing deadlines"
        );
        ensure!(
            (1..=10_737_418_240).contains(&l.output_bytes)
                && l.derived_bytes >= l.output_bytes
                && l.artifacts > 0
                && l.artifacts <= 2000
                && l.chunks > 0
                && l.chunks <= 100000
                && (3..=64).contains(&l.generations),
            "invalid processing output limits"
        );
        ensure!(
            !self.temporal.host.is_empty()
                && !self.temporal.namespace.is_empty()
                && !self.temporal.task_queue.is_empty()
                && (1..=30).contains(&self.temporal.rpc_timeout_seconds)
                && (1..=30).contains(&self.temporal.connect_timeout_seconds),
            "invalid processing Temporal settings"
        );
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn worker_configuration_rejects_invalid_processing_even_when_admission_is_disabled() {
        let mut config: crate::config::Configuration =
            serde_yaml_ng::from_str(include_str!("../../config/configuration.yaml")).unwrap();
        config.storage.content = Some(serde_json::from_value(serde_json::json!({"endpoint":"http://localhost:9000","bucket":"originals","allow_insecure":true})).unwrap());
        config.scheduler.processing = Some(serde_json::from_value(serde_json::json!({
            "enabled":false,"temporal":{"host":"localhost:7233","namespace":"default","task_queue":"ingestion"},
            "worker_contract_file":"contract.json", "worker":{"issuer":"http://localhost/realms/app","audience":"app","client_id":"worker"},
            "derived":{"endpoint":"http://localhost:9000","bucket":"derived","allow_insecure":true}
        })).unwrap());
        assert!(config.validate().is_ok());
        config
            .scheduler
            .processing
            .as_mut()
            .unwrap()
            .limits
            .poll_seconds = 0;
        assert!(config.validate().is_err());
        config
            .scheduler
            .processing
            .as_mut()
            .unwrap()
            .limits
            .poll_seconds = 1;
        config.scheduler.processing.as_mut().unwrap().derived.bucket = "originals".into();
        assert!(config.validate().is_err());
    }
}
